export const productionKey='apparition.admin.production.v1';
const blank=c=>({key:c.key,orderId:c.orderId,itemIndex:c.itemIndex,unit:c.unit,picked:{},bomPlans:{},revision:0});
export function createProductionStore(storage,{lock}={}){
 function read(){let raw;try{raw=storage.getItem(productionKey);}catch{throw new Error('Production storage is unavailable.');}if(raw===null)return {version:1,records:[]};try{const d=JSON.parse(raw),keys=new Set();if(d.version!==1||!Array.isArray(d.records))throw new Error();for(const r of d.records){if(!r.key||keys.has(r.key)||!r.orderId||!Number.isSafeInteger(r.revision)||!r.picked||!r.bomPlans)throw new Error();keys.add(r.key);}return d;}catch{throw new Error('Saved production records could not be read. Nothing was reset.');}}
 return {get:c=>structuredClone(read().records.find(r=>r.key===c.key)||blank(c)),async update(c,change){if(!lock)throw new Error('Safe production saving requires browser lock support.');return lock(productionKey,()=>{const d=read(),i=d.records.findIndex(r=>r.key===c.key),r=structuredClone(i<0?blank(c):d.records[i]);change(r);if(r.key!==c.key||r.orderId!==c.orderId||r.itemIndex!==c.itemIndex||r.unit!==c.unit)throw new Error('Production identity cannot be changed.');r.revision++;r.updatedAt=new Date().toISOString();if(i<0)d.records.push(r);else d.records[i]=r;try{storage.setItem(productionKey,JSON.stringify(d));}catch{throw new Error('Production record could not be saved. Browser storage may be full or disabled.');}return structuredClone(r);});}};
}
export const browserProductionStore=()=>createProductionStore(localStorage,{lock:navigator.locks?(key,fn)=>navigator.locks.request(key,fn):null});
